            if set(item) != {"op", "key"}:
                raise ValueError(
                    "delete change must carry exactly op and key: %r"
                    % (list(item),)
                )
            _validate_key(item["key"])
        else:
            raise ValueError(
                "change op must be 'set' or 'delete', got %r" % (op,)
